"""Scene replays captured from the official iPhone Govee app."""

from types import MappingProxyType


def _frames(hex_data: str) -> tuple[bytes, ...]:
    """Split an exact recording into 20-byte H617A frames."""
    return tuple(bytes.fromhex(hex_data[i : i + 40]) for i in range(0, len(hex_data), 40))


